function examSliceV29(u,start,end){const out=[];let pos=0;for(const n of u.ruby||[{text:u.ja}]){const a=Math.max(start,pos),b=Math.min(end,pos+n.text.length);if(a<b)out.push(a===pos&&b===pos+n.text.length?n:{text:n.text.slice(a-pos,b-pos)});pos+=n.text.length}return jp(u.ja.slice(start,end),out)}
