function examPaperHTMLV29(paper){let number=0;return `${paper.submitted?examSummaryV29(paper):''}<form id="exam-paper">${ExamEngineV29.sections.map(section=>{const qs=paper.questions.filter(q=>q.section===section);return qs.length?`<section class="exam-section"><h2>${EXAM_SECTIONS_V29[section]}<small>${qs.length}题</small></h2>${qs.map(q=>{const i=number++;return paper.submitted&&examFilterV29==='wrong'&&ExamEngineV29.correct(q,paper.answers[q.id])?'':examQuestionHTMLV29(q,i,paper)}).join('')}</section>`:''}).join('')}<div class="exam-submit">${paper.submitted?button('再做本卷','exam-retry','','action'): '<button type="submit" class="action primary">提交整卷</button>'}</div></form>`}
